CREATE TABLE render_manifests (id TEXT PRIMARY KEY NOT NULL,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,version_no INTEGER NOT NULL CHECK(version_no>0),status TEXT NOT NULL CHECK(status IN('CANDIDATE','APPROVED','SUPERSEDED')),content_hash TEXT NOT NULL,manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),created_at TEXT NOT NULL,UNIQUE(project_id,version_no),UNIQUE(id,project_id));
